) / approved_m3, by region and country", "version": 1, "rounding": "nearest 0.01", "metric_id": "cost_per_m3", "numerator": null, "change_note": "Initial registered definition (V473)", "denominator": null, "formula_ref": "get_cost_per_m3", "effective_to": null, "effective_from": "2024-01-01"}, {"formula": "count(work_orders) where status not in terminal set", "version": 1, "rounding": "nearest 0.01", "metric_id": "open_work_orders", "numerator": null, "change_note": "Initial registered definition (V473)", "denominator": null, "formula_ref": "get_maintenance_snapshot", "effective_to": null, "effective_from": "2024-01-01"}, {"formula": "count(distinct asset_no) in vehicle_fleet", "version": 1, "rounding": "nearest 0.01", "metric_id": "fleet_size", "numerator": null, "change_note": "Initial registered definition (V473)", "denominator": null, "formula_ref": "count vehicle_fleet", "effective_to": null, "effective_from": "2024-01-01"}, {"formula": "count(accidents) by incident_date", "version": 1, "rounding": "nearest 0.01", "metric_id": "accidents_total", "numerator": null, "change_note": "Initial registered definition (V473)", "denominator": null, "formula_ref": "claimsAnalytics/analytics", "effective_to": null, "effective_from": "2024-01-01"}, {"formula": "sum(recovered_amount) per country", "version": 1, "rounding": "nearest 0.01", "metric_id": "claims_recovered", "numerator": null, "change_note": "Initial registered definition (V473)", "denominator": null, "formula_ref": "claimsAnalytics.analyzeClaims", "effective_to": null, "effective_from": "2024-01-01"}, {"formula": "completed inspections / due inspections", "version": 1, "rounding": "nearest 0.01", "metric_id": "inspection_compliance", "numerator": null, "change_note": "Initial registered definition (V473)", "denominator": null, "formula_ref": "kpiEngine.inspectionCompliance", "effective_to": null, "effective_from": "2024-01-01"}, {"formula": "scrapped tyres / total tyres", "version": 1, "rounding": "nearest 0.01